import fs from 'node:fs';import assert from 'node:assert/strict';import {encodeDeployData,keccak256,parseAbi,stringToHex} from './enclave/node_modules/viem/_esm/index.js';import{LeaseReader}from'./enclave/network/lease-reader.mjs';import{compileHostOwnership}from'./enclave/scripts/deploy-secret-vault-v2.mjs';
const p=JSON.parse(fs.readFileSync('outputs/host-ownership-release/transaction.json'));
const reader=new LeaseReader({rpc:['https://base-rpc.publicnode.com','https://base.drpc.org','https://mainnet.base.org'],addressBook:'0xab214342d5A490150A4A977063A2f88E21F80907'});
const observation=await reader.agreed(async(c,blockNumber)=>{const registry=await c.readContract({address:reader.addressBook,abi:parseAbi(['function addr(bytes32) view returns(address)']),functionName:'addr',args:[stringToHex('registry',{size:32})],blockNumber});const code=await c.getCode({address:registry,blockNumber});return{registry:registry.toLowerCase(),registryCodeHash:keccak256(code)};});
assert.equal(observation.registry,p.authorityObservation.registry);assert.equal(observation.registryCodeHash,p.authorityObservation.registryCodeHash);
const compiled=compileHostOwnership();const data=encodeDeployData({abi:compiled.abi,bytecode:compiled.bytecode,args:[observation.registry]});assert.equal(data,p.transaction.data);
const gas=await reader.clients[1].estimateGas({account:p.transaction.from,data,value:0n});
const simulated=await reader.clients[1].call({account:p.transaction.from,data,value:0n});assert.ok(simulated.data&&simulated.data!=='0x');
const out={expectedRuntimeCodeHash:keccak256(simulated.data),status:'ready-for-owner-signature',checkedAt:new Date().toISOString(),purpose:p.purpose,authorityObservation:observation,transaction:{chainId:8453,from:p.transaction.from,value:'0x0',data},estimatedGas:gas.toString(),notes:['Deploys the contract only. No host is enrolled and no policy is activated by this transaction.','Host owners can set policy only for their own enrolled hosts; no global veto administrator exists.']};fs.writeFileSync('outputs/host-ownership-release/signing-request.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,estimatedGas:out.estimatedGas,registry:observation.registry}));
